{
  "source_id": "TEXT",
  "cast": [
    {
      "id": "P01",
      "name": "格雷戈尔·萨姆沙"
    },
    {
      "id": "P02",
      "name": "母亲"
    },
    {
      "id": "P03",
      "name": "父亲"
    },
    {
      "id": "P04",
      "name": "妹妹"
    }
  ],
  "locations": [
    {
      "id": "L01",
      "name": "格雷戈尔的卧室"
    }
  ],
  "scenes": [
    {
      "sceneId": "L01",
      "characters": [
        "P01"
      ],
      "flow": [
        {
          "action": "格雷戈尔从不安的梦中醒来，仰面躺着，费力抬起沉重的头。"
        },
        {
          "action": "被子从他腹部的弧形硬片上滑落，露出许多细弱的腿在空中无助地颤动。"
        },
        {
          "speaker": "P01",
          "line": "我出什么事了？",
          "mode": "spoken",
          "delivery": "声音发哑"
        },
        {
          "action": "他环顾熟悉的四片墙壁，目光扫过桌上摊开的货品选样和墙上的金框画。"
        },
        {
          "speaker": "P01",
          "line": "这不是梦，房间还是我的房间。",
          "mode": "spoken"
        },
        {
          "action": "他望向窗户，雨点敲在铁皮窗檐上，屋里一片阴沉。"
        },
        {
          "speaker": "P01",
          "line": "要是再睡一会儿，把这些蠢事忘掉就好了。",
          "mode": "spoken",
          "delivery": "疲惫"
        },
        {
          "action": "他用力把身子翻向右侧，却又摇晃着弹回仰卧，试了一次又一次。"
        },
        {
          "speaker": "P01",
          "line": "翻不过去。老天，我干的是什么苦差事。",
          "mode": "spoken",
          "delivery": "喘着粗气"
        },
        {
          "action": "他闭上眼睛不再看那些乱动的腿，直到腰侧一阵钝痛才停下来。"
        }
      ]
    },
    {
      "sceneId": "L01",
      "characters": [
        "P01",
        "P02",
        "P03",
        "P04"
      ],
      "flow": [
        {
          "action": "格雷戈尔把背蹭到床柱边，好抬起头查看肚子上发痒的地方。"
        },
        {
          "speaker": "P01",
          "line": "这些白点是什么东西？",
          "mode": "spoken"
        },
        {
          "action": "他伸出一条细腿去摸，刚碰到就猛地缩回，全身一阵寒战。"
        },
        {
          "speaker": "P01",
          "line": "日复一日奔波，吃饭不定时。",
          "mode": "spoken",
          "delivery": "越说越恼"
        },
        {
          "speaker": "P01",
          "line": "别的推销员过得像老爷。",
          "mode": "spoken"
        },
        {
          "speaker": "P01",
          "line": "让这一切都见鬼去吧！",
          "mode": "spoken"
        },
        {
          "speaker": "P01",
          "line": "等我还清爸妈欠老板的钱，我就去辞职。",
          "mode": "spoken"
        },
        {
          "action": "他望向柜子上的闹钟，指针毫不迟疑地走过六点三刻。"
        },
        {
          "speaker": "P01",
          "line": "天哪，六点三刻了！火车七点开。",
          "mode": "spoken",
          "delivery": "急切"
        },
        {
          "speaker": "P01",
          "line": "样品没收拾好，五点那班车也错过了。",
          "mode": "spoken"
        },
        {
          "speaker": "P01",
          "line": "请假？我五年没生过病，他准会带着医生来。",
          "mode": "spoken"
        },
        {
          "action": "床头那边的门上响起小心翼翼的敲门声。"
        },
        {
          "speaker": "P02",
          "line": "格雷戈尔，六点三刻了，你不是还得赶火车吗？",
          "mode": "spoken",
          "delivery": "声音柔和"
        },
        {
          "action": "格雷戈尔一惊，张口回答，声音里夹着一股压不住的尖声。"
        },
        {
          "speaker": "P01",
          "line": "是的，是的，谢谢妈妈，我这就起床。",
          "mode": "spoken",
          "delivery": "尖细发颤"
        },
        {
          "action": "母亲踢踢踏踏走远，父亲随即用拳头敲响侧面那扇门。"
        },
        {
          "speaker": "P03",
          "line": "格雷戈尔！格雷戈尔！你怎么啦？",
          "mode": "spoken",
          "delivery": "低沉急促"
        },
        {
          "speaker": "P03",
          "line": "格雷戈尔！格雷戈尔！",
          "mode": "spoken",
          "delivery": "压低声音再催"
        },
        {
          "action": "另一侧的门传来妹妹轻轻的敲门声。"
        },
        {
          "speaker": "P04",
          "line": "格雷戈尔？你是不是不舒服？你需要什么吗？",
          "mode": "spoken",
          "delivery": "带着担心"
        },
        {
          "speaker": "P01",
          "line": "我这就好了。",
          "mode": "spoken",
          "delivery": "一字一顿，小心发音"
        },
        {
          "speaker": "P04",
          "line": "格雷戈尔，开开门，我求你了。",
          "mode": "spoken",
          "delivery": "轻声恳求"
        },
        {
          "action": "格雷戈尔一动不动地躺着，目光停在锁住的门上。"
        }
      ]
    }
  ]
}
